-- Apply once in Supabase SQL editor. No seeded users, scores, engagement, or prizes.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, username text not null check(length(username) between 2 and 32), created_at timestamptz not null default now());
create table public.wallet_links(user_id uuid primary key references public.profiles on delete cascade,address text unique not null,verified_at timestamptz not null default now());
create table public.missions(id uuid primary key default gen_random_uuid(), title text not null, description text not null,points integer not null check(points between 0 and 10000),action_url text,requirements text not null default 'Submit a public evidence URL for manual review.',active boolean not null default false);
create table public.mission_submissions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,mission_id uuid not null references public.missions,evidence text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now(),unique(user_id,mission_id));
create table public.mission_completions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,mission_id uuid not null references public.missions,created_at timestamptz not null default now(),unique(user_id,mission_id));
create table public.point_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,mission_id uuid not null references public.missions,amount integer not null check(amount>=0),created_at timestamptz not null default now(),unique(user_id,mission_id));
create table public.leaderboard_snapshots(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,rank integer not null,period text not null,captured_at timestamptz not null default now());
create table public.social_posts(id uuid primary key default gen_random_uuid(),title text not null,url text not null,image_path text,video_path text,views bigint check(views>=0),likes bigint check(likes>=0),published_at timestamptz not null default now(),published boolean not null default false);
create table public.rewards(id uuid primary key default gen_random_uuid(),title text not null,description text not null,image_path text,rules text not null,eligibility text not null,status text not null default 'coming_soon' check(status in ('coming_soon','active','closed')),claim_url text);
create table public.reward_claims(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,reward_id uuid not null references public.rewards,status text not null default 'pending',created_at timestamptz not null default now(),unique(user_id,reward_id));
create table public.site_settings(key text primary key,value jsonb not null);
create table public.wallet_challenges(user_id uuid primary key references public.profiles,nonce text not null,message text not null,expires_at timestamptz not null);
create table public.rate_limits(key text primary key,window_start timestamptz not null default now(),hits integer not null default 1);
create index points_by_time on public.point_transactions(created_at,user_id);
create index submissions_by_status on public.mission_submissions(status);
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,username) values(new.id,'Crew-'||substr(new.id::text,1,8)); return new; end $$;
create trigger on_new_user after insert on auth.users for each row execute function public.new_profile();
-- No browser writes: all mutations are server validated or reviewed in the trusted SQL dashboard.
do $$ declare t text; begin foreach t in array array['profiles','wallet_links','missions','mission_submissions','mission_completions','point_transactions','leaderboard_snapshots','social_posts','rewards','reward_claims','site_settings','wallet_challenges','rate_limits'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end $$;
grant select on public.profiles,public.wallet_links,public.mission_submissions,public.mission_completions,public.point_transactions,public.reward_claims to authenticated;
create policy own_profile on public.profiles for select to authenticated using(id=auth.uid());
create policy own_wallet on public.wallet_links for select to authenticated using(user_id=auth.uid());
create policy own_submissions on public.mission_submissions for select to authenticated using(user_id=auth.uid());
create policy own_completions on public.mission_completions for select to authenticated using(user_id=auth.uid());
create policy own_points on public.point_transactions for select to authenticated using(user_id=auth.uid());
create policy own_claims on public.reward_claims for select to authenticated using(user_id=auth.uid());
create function public.consume_rate_limit(p_key text,p_limit integer) returns boolean language plpgsql security definer set search_path=public as $$ declare n integer; begin insert into rate_limits(key) values(p_key) on conflict(key) do update set hits=case when rate_limits.window_start<now()-interval '1 minute' then 1 else rate_limits.hits+1 end,window_start=case when rate_limits.window_start<now()-interval '1 minute' then now() else rate_limits.window_start end returning hits into n;return n<=p_limit;end $$;
create function public.approve_submission(p_submission uuid) returns void language plpgsql security definer set search_path=public as $$ declare s mission_submissions; p integer; begin select * into s from mission_submissions where id=p_submission for update; if not found then raise exception 'Submission not found'; end if; if s.status='approved' then return;end if; if s.status<>'pending' then raise exception 'Submission is not pending';end if; select points into p from missions where id=s.mission_id and active=true for share; if not found then raise exception 'Mission inactive';end if; insert into mission_completions(user_id,mission_id) values(s.user_id,s.mission_id);insert into point_transactions(user_id,mission_id,amount) values(s.user_id,s.mission_id,p);update mission_submissions set status='approved' where id=s.id;end $$;
create function public.link_wallet(p_user uuid,p_nonce text,p_address text) returns boolean language plpgsql security definer set search_path=public as $$ begin delete from wallet_challenges where user_id=p_user and nonce=p_nonce and expires_at>now(); if not found then return false;end if;insert into wallet_links(user_id,address) values(p_user,p_address) on conflict(user_id) do update set address=excluded.address,verified_at=now();return true;end $$;
create function public.leaderboard(p_period text default 'all',p_offset integer default 0,p_limit integer default 20) returns table(user_id uuid,username text,score bigint,rank bigint) language sql stable security definer set search_path=public as $$ select p.id,p.username,sum(t.amount)::bigint,row_number() over(order by sum(t.amount) desc,p.id) from profiles p join point_transactions t on t.user_id=p.id where (p_period='all' or t.created_at>=case when p_period='today' then date_trunc('day',now() at time zone 'UTC') at time zone 'UTC' else date_trunc('week',now() at time zone 'UTC') at time zone 'UTC' end) group by p.id,p.username order by sum(t.amount) desc,p.id limit least(greatest(p_limit,1),100) offset greatest(p_offset,0) $$;
create function public.profile_rank(p_user uuid) returns bigint language sql stable security definer set search_path=public as $$ select r.rank from (select user_id,row_number() over(order by sum(amount) desc,user_id) rank from point_transactions group by user_id) r where r.user_id=p_user $$;
revoke all on function public.consume_rate_limit(text,integer),public.approve_submission(uuid),public.link_wallet(uuid,text,text),public.leaderboard(text,integer,integer),public.profile_rank(uuid),public.new_profile() from public,anon,authenticated;
grant execute on function public.consume_rate_limit(text,integer),public.approve_submission(uuid),public.link_wallet(uuid,text,text),public.leaderboard(text,integer,integer),public.profile_rank(uuid) to service_role;